html:
{%- set print = get_print_settings() -%}
{%- set totals = get_print_totals(doc) -%}
<style>
  .books-print { background: #fff; color: #171717; padding: 16px 12px; font-size: 13px; line-height: 17.55px; letter-spacing: 0.02em; }
  .books-print table { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .books-print td, .books-print th { padding: 0; border: 0; color: inherit; text-align: left; vertical-align: top; font-weight: inherit; }
  .books-print .books-right { text-align: right; }
  .books-print .books-bold { font-weight: bold; }
  .books-print .books-xs { font-size: 12px; line-height: 16.2px; letter-spacing: 0.02em; }
  .books-print .books-header { text-align: center; }
  .books-print .books-logo { display: block; max-width: 100%; max-height: 64px; margin: 0 auto 4px; }
  .books-print .books-company-name { font-size: 17px; line-height: 22.95px; letter-spacing: 0.02em; font-weight: bold; }
  .books-print .books-address { margin-top: 4px; }
  .books-print .books-title { margin-top: 12px; font-size: 16px; line-height: 21.6px; letter-spacing: 0.02em; font-weight: bold; }
  .books-print .books-section { margin-top: 8px; }
  .books-print .books-details th { padding-right: 8px; font-weight: bold; }
  .books-print .books-items td, .books-print .books-items th { padding: 4px 4px 4px 0; }
  .books-print .books-items td:last-child, .books-print .books-items th:last-child { padding-right: 0; }
  .books-print .books-items th { border-top: 1px solid #000; border-bottom: 1px solid #000; font-weight: bold; }
  .books-print .books-lines { line-height: 18px; }
  .books-print .books-totals { border-top: 1px solid #000; padding: 4px 0; }
  .books-print .books-grand-total { border-top: 1px solid #000; border-bottom: 1px solid #000; padding: 8px 0; font-size: 16px; line-height: 24px; letter-spacing: 0.02em; font-weight: bold; }
  .books-print .books-payments th { font-weight: bold; }
  .books-print .books-thanks { margin-top: 16px; line-height: 19.5px; text-align: center; }
</style>
<main class="books-print" style="font-family: {{ print.font }}">
  <header class="books-header">
    {%- if print.display_logo and print.logo %}
    <img class="books-logo" src="{{ print.logo }}">
    {%- endif %}
    <div class="books-company-name" style="color: {{ print.color }}">{{ (print.company_name or "") | e }}</div>
    {%- if print.address %}
    <div class="books-xs books-address">{{ print.address | e }}</div>
    {%- endif %}
    {%- if print.phone %}
    <div class="books-xs">{{ print.phone | e }}</div>
    {%- endif %}
    {%- if print.email %}
    <div class="books-xs">{{ print.email | e }}</div>
    {%- endif %}
    {%- if print.gstin %}
    <div class="books-xs">{{ _("GSTIN") }}: {{ print.gstin | e }}</div>
    {%- endif %}
    <div class="books-title">{{ _("Invoice") }}</div>
  </header>

  <table class="books-section books-xs books-lines books-details">
    <colgroup>
      <col style="width: 88px">
      <col>
    </colgroup>
    <tr>
      <th>{{ _("Invoice No") }}</th>
      <td>{{ doc.name | e }}</td>
    </tr>
    <tr>
      <th>{{ _("Customer") }}</th>
      <td>{{ (doc.party or "") | e }}</td>
    </tr>
    <tr>
      <th>{{ _("Date") }}</th>
      <td>
        {{- books_format(doc.date, "Date") }}
        {%- if print.display_time %} {{ frappe.utils.format_time(doc.date) }}{% endif -%}
      </td>
    </tr>
  </table>

  <table class="books-section books-xs books-lines books-items">
    <colgroup>
      <col style="width: 20px">
      <col>
      <col style="width: 36px">
      <col style="width: 60px">
      <col style="width: 64px">
    </colgroup>
    <tr>
      <th>#</th>
      <th>{{ _("Item") }}</th>
      <th class="books-right">{{ _("Qty") }}</th>
      <th class="books-right">{{ _("Rate") }}</th>
      <th class="books-right">{{ _("Amount") }}</th>
    </tr>
    {%- for row in doc.items %}
    <tr>
      <td>{{ loop.index }}</td>
      <td>{{ (row.item or "") | e }}</td>
      <td class="books-right">{{ books_format(row.transfer_quantity, "Float") }}</td>
      <td class="books-right">{{ books_format(row.transfer_rate, "Currency", doc.currency) }}</td>
      <td class="books-right">{{ books_format(row.amount, "Currency", doc.currency) }}</td>
    </tr>
    {%- endfor %}
  </table>

  <div class="books-xs books-lines books-totals">
  <table>
    <tr>
      <td>{{ _("Subtotal") }}</td>
      <td class="books-right">{{ books_format(doc.net_total, "Currency", doc.currency) }}</td>
    </tr>
    {%- if doc.total_discount %}
    <tr>
      <td>{{ _("Discount") }}</td>
      <td class="books-right">{{ books_format(doc.total_discount, "Currency", doc.currency) }}</td>
    </tr>
    {%- endif %}
    {%- for tax in doc.taxes %}
    <tr>
      <td>{{ tax.account | e }}</td>
      <td class="books-right">{{ books_format(tax.amount, "Currency", doc.currency) }}</td>
    </tr>
    {%- endfor %}
    {%- if doc.loyalty_points_amount %}
    <tr>
      <td>{{ _("Loyalty Points Redeemed") }}</td>
      <td class="books-right">{{ books_format(doc.loyalty_points_amount, "Currency", doc.currency) }}</td>
    </tr>
    {%- endif %}
  </table>
  </div>

  <div class="books-grand-total">
  <table>
    <tr>
      <td>{{ _("Grand Total") }}</td>
      <td class="books-right">{{ books_format(doc.grand_total, "Currency", doc.currency) }}</td>
    </tr>
  </table>
  </div>

  {%- if totals.payment_details %}
  <table class="books-section books-xs books-lines books-payments">
    <colgroup>
      <col>
      <col style="width: 80px">
      <col style="width: 80px">
    </colgroup>
    <tr>
      <th>{{ _("Payment Method") }}</th>
      <th class="books-right">{{ _("Paid") }}</th>
      <th class="books-right">{{ _("Balance") }}</th>
    </tr>
    {%- for payment in totals.payment_details %}
    <tr>
      <td>{{ payment.payment_method | e }}</td>
      <td class="books-right">{{ books_format(payment.amount, "Currency") }}</td>
      <td class="books-right">{{ books_format(payment.outstanding_amount, "Currency") }}</td>
    </tr>
    {%- endfor %}
  </table>
  {%- endif %}

  <div class="books-thanks">{{ _("Thank you! Please visit again.") }}</div>
</main>
